import java.nio.file.*;
import java.util.*;
import java.util.zip.*;
import org.objectweb.asm.*;
import org.objectweb.asm.tree.*;
import org.objectweb.asm.tree.analysis.*;
import org.objectweb.asm.util.*;
public final class DandanMotionContractProofV1 implements Opcodes {
    private static final String SELF="net/farmingtales/ftboss/entity/EasterBossEntity",ACCESS="net/farmingtales/ftboss/dandanmotion/MotionAccess";
    private static void require(boolean value,String name){if(!value)throw new AssertionError(name);}
    private static ClassNode read(ZipFile jar,String name)throws Exception{ClassNode result=new ClassNode();new ClassReader(jar.getInputStream(jar.getEntry(name+".class")).readAllBytes()).accept(result,0);return result;}
    private static String body(MethodNode source){MethodNode copy=new MethodNode(source.access,source.name,source.desc,source.signature,source.exceptions.toArray(String[]::new));source.accept(copy);for(AbstractInsnNode instruction:copy.instructions.toArray())if(instruction instanceof FrameNode||instruction instanceof LineNumberNode)copy.instructions.remove(instruction);Set<LabelNode> targets=new HashSet<>();for(AbstractInsnNode instruction:copy.instructions.toArray())if(instruction instanceof JumpInsnNode branch)targets.add(branch.label);for(AbstractInsnNode instruction:copy.instructions.toArray())if(instruction instanceof LabelNode label&&!targets.contains(label))copy.instructions.remove(label);Textifier text=new Textifier();copy.instructions.accept(new TraceMethodVisitor(text));return text.getText().toString();}
    private static void map(MethodNode method){Map<String,String> nbt=Map.ofEntries(Map.entry("m_128356_","putLong"),Map.entry("m_128359_","putString"),Map.entry("m_128365_","put"),Map.entry("m_128379_","putBoolean"),Map.entry("m_128405_","putInt"),Map.entry("m_128423_","get"),Map.entry("m_128441_","contains"),Map.entry("m_128451_","getInt"),Map.entry("m_128454_","getLong"),Map.entry("m_128461_","getString"),Map.entry("m_128471_","getBoolean"),Map.entry("m_128473_","remove"),Map.entry("m_6426_","copy"));for(AbstractInsnNode instruction:method.instructions.toArray()){if(instruction instanceof FieldInsnNode field){if(field.owner.equals(SELF)&&field.name.equals("f_19804_"))field.name="entityData";if(field.owner.equals("net/minecraft/world/level/Level")&&field.name.equals("f_46443_"))field.name="isClientSide";}if(instruction instanceof MethodInsnNode call){if(call.owner.equals("net/minecraft/network/syncher/SynchedEntityData")){if(call.name.equals("m_135370_"))call.name="get";if(call.name.equals("m_135381_"))call.name="set";}if(call.owner.equals(SELF)&&call.name.equals("m_9236_"))call.name="level";if(call.owner.equals("net/minecraft/world/level/Level")&&call.name.equals("m_46467_"))call.name="getGameTime";if(call.owner.equals("net/minecraft/nbt/CompoundTag")||call.owner.equals("net/minecraft/nbt/Tag"))call.name=nbt.getOrDefault(call.name,call.name);}}}
    public static void main(String[] arguments)throws Exception{try(ZipFile base=new ZipFile(arguments[0]);ZipFile forge=new ZipFile(arguments[1])){
        ClassNode current=read(base,SELF),before=read(base,SELF),original=read(forge,SELF),access=read(base,ACCESS),originalAccess=read(forge,ACCESS);require(original.interfaces.contains(ACCESS)&&!current.interfaces.contains(ACCESS),"Expected missing original interface");require(current.fields.stream().anyMatch(field->field.name.equals("DATA_COMBAT_ANIMATION")&&field.desc.equals("Lnet/minecraft/network/syncher/EntityDataAccessor;")),"Existing original shared combat animation channel absent");require(access.methods.size()==2&&originalAccess.methods.size()==2,"Unexpected interface size");
        int added=0;for(MethodNode contract:access.methods){require(contract.name.equals("dandanMotionData")&&current.methods.stream().noneMatch(method->method.name.equals(contract.name)&&method.desc.equals(contract.desc)),"Unexpected existing motion getter/setter");MethodNode authority=original.methods.stream().filter(method->method.name.equals(contract.name)&&method.desc.equals(contract.desc)).findFirst().orElseThrow();require((authority.access&ACC_PUBLIC)!=0,"Original method is not public");MethodNode copied=new MethodNode(authority.access,authority.name,authority.desc,authority.signature,authority.exceptions.toArray(String[]::new));authority.accept(copied);map(copied);List<AbstractInsnNode> executable=Arrays.stream(copied.instructions.toArray()).filter(instruction->instruction.getOpcode()>=0).toList();require(executable.size()==6,"Unexpected original getter/setter body");require(executable.stream().filter(instruction->instruction instanceof FieldInsnNode field&&field.name.equals("DATA_COMBAT_ANIMATION")).count()==1,"Original getter/setter uses another channel");require(executable.stream().noneMatch(instruction->instruction instanceof TypeInsnNode type&&type.getOpcode()==NEW),"Unexpected data allocation/copy semantics");current.methods.add(copied);added++;}
        int helperEquivalent=0;String server="net/farmingtales/ftboss/dandanmotion/MotionServer";ClassNode oldServer=read(forge,server),nowServer=read(base,server);require(oldServer.methods.size()==nowServer.methods.size(),"Motion helper method count differs");for(MethodNode authority:oldServer.methods){MethodNode actual=nowServer.methods.stream().filter(method->method.name.equals(authority.name)&&method.desc.equals(authority.desc)).findFirst().orElseThrow();map(authority);require(body(authority).equals(body(actual)),"Original motion helper differs:"+authority.name);helperEquivalent++;}
        current.interfaces.add(ACCESS);require(current.fields.size()==before.fields.size(),"Accessor IDs or fields changed");for(int index=0;index<before.methods.size();index++)require(body(current.methods.get(index)).equals(body(before.methods.get(index))),"Existing entity method changed:"+before.methods.get(index).name);
        ClassWriter writer=new ClassWriter(ClassWriter.COMPUTE_MAXS);current.accept(writer);byte[] bytes=writer.toByteArray();ClassNode result=new ClassNode();new ClassReader(bytes).accept(result,0);int verified=0;for(MethodNode method:result.methods)if((method.access&(ACC_ABSTRACT|ACC_NATIVE))==0){new Analyzer<>(new BasicVerifier()).analyze(SELF,method);verified++;}
        for(MethodNode contract:access.methods){MethodNode actual=result.methods.stream().filter(method->method.name.equals(contract.name)&&method.desc.equals(contract.desc)).findFirst().orElseThrow();MethodNode authority=original.methods.stream().filter(method->method.name.equals(contract.name)&&method.desc.equals(contract.desc)).findFirst().orElseThrow();map(authority);require(body(actual).equals(body(authority)),"Mapped original method differs after output");}
        Path output=Path.of(arguments[2]).resolve(SELF+".class");Files.createDirectories(output.getParent());Files.write(output,bytes);System.out.println("failures=0;originalInterfaceRestored=1;exactMappedOriginalMethodsAdded="+added+";existingEntityMethodsPreserved="+before.methods.size()+";entityMethodsBasicVerified="+verified+";originalHelperMethodsEquivalent="+helperEquivalent+";newDataAccessors=0;existingDataIdsPreserved=true;gameplayHooksNotActivated=true");
    }}
}
